        internal static IEnumerable<KeyValuePair<int, string>> GetCoordinateSystemDefinitions()
        {
            for (int i = 0; i < CoordinateSystems.Length; i++)
            {
                var record = CoordinateSystems[i];
                yield return new KeyValuePair<int, string>(record.Srid, StringPool[record.WktIndex]);
            }
        }
